// mem_shims_lambdalib.sv
// FIRRTL _ext wrappers using la_dpram / la_spram lambdalib interfaces

//////////////////////////////////////////////////////////////////////
// cc_dir_0_ext -> 64x47 -> la_dpram 64x64 (pad to 64b)
//////////////////////////////////////////////////////////////////////
module cc_dir_0_ext (
  input  [5:0]  R0_addr,
  input         R0_en,
  input         R0_clk,
  output [46:0] R0_data,

  input  [5:0]  W0_addr,
  input         W0_en,
  input         W0_clk,
  input  [46:0] W0_data,
  input  [46:0] W0_mask
);

  wire [63:0] rdata;

  la_dpram #(.DW(64), .AW(6)) mem (
    .wr_clk  (W0_clk),
    .wr_ce   (W0_en),
    .wr_we   (1'b1),
    .wr_addr (W0_addr),
    .wr_din  ({17'b0, W0_data}),
    .wr_wmask({17'b0, W0_mask}),

    .rd_clk  (R0_clk),
    .rd_ce   (R0_en),
    .rd_addr (R0_addr),
    .rd_dout (rdata),

    .vss(1'b0), .vdd(1'b1), .vddio(1'b1),
    .ctrl('0), .test('0)
  );

  assign R0_data = rdata[46:0];

endmodule

